/**
 * How Swallowtail butterfly (`agehacho`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/agehacho";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Seen from the side, every edge an arc of a struck circle or a ruled line. The near forewing stands upright behind a ruled front edge: a band of four round lobes with three eyes, each a ring with two white arcs under it, and at the band's foot three scallops, each a pair of white lines. Below the band the veins are white lines ruled from the centre of the head, a long one to each point of the scallops and a short one between. The far forewing shows at the left with two eyes and a pointed tip. The hindwing lies behind at the right: its veins are arcs of one compass width, their centres stepped along a line, with two lobes at its rim and two forked tails above. One feeler curls above the far wing, its stem down the front edge; the other runs along the far wing's foot to a small hook. The head is a dome inside two rings, with a ringed eye; three legs, two blades and three bars are drawn below.","ja":"横から見た姿で、どの辺も、コンパスで描いた円の弧か、定規で引いた直線です。手前の前翅は、直線の前縁の後ろに立てます。丸い山を四つ並べた帯に目玉模様を三つ（輪と、その下の白い弧二本）入れ、帯の下の縁は、白い線二本ずつの波形を三つ並べます。帯の下の翅脈は、頭の中心から引いた白い線で、波形の角へ長い線を一本ずつ、その間に短い線を入れます。左奥に、目玉模様二つと尖った先のある奥の前翅がのぞきます。右奥の後翅の翅脈は、同じコンパス幅の弧で、中心を一本の線に沿ってずらして描き、縁に丸い山二つ、上に二股の尾を二つつけます。触角は、一本を奥の翅の上で巻いて、軸を前縁に沿わせ、もう一本を奥の翅の下の縁に沿わせて小さく曲げます。頭は二重の輪の中の半円で、輪のある目を入れます。下に脚三本、葉の形を二つ、棒を三本描きます。"};

export default construction;
export { construction, description };
